import android.Manifest;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.os.Build;
import android.os.Bundle;
import android.os.Handler;
import android.view.View;
import android.widget.Button;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AlertDialog;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.app.ActivityCompat;
import androidx.core.content.ContextCompat;

import com.fangames.survivalmerge.R;
import com.fangames.survivalmerge.SurvivalMergeApp;
import com.fangames.survivalmerge.managers.FirebaseManager;
import com.fangames.survivalmerge.managers.GameManager;
import com.fangames.survivalmerge.managers.MonetizationManager;
import com.fangames.survivalmerge.models.Player;

/**
 * Main game screen - Merge grid + Tower defense gameplay
 * REQUIREMENT #9: Implements Android 13+ notification permission
 */
public class MainActivity extends AppCompatActivity {

    private static final int NOTIFICATION_PERMISSION_REQUEST = 100;

    private GameManager gameManager;
    private MonetizationManager monetizationManager;
    private FirebaseManager firebaseManager;
    private Player player;

    private TextView txtLevel;
    private TextView txtWave;
    private TextView txtScore;
    private TextView txtGold;
    private TextView txtGems;
    private TextView txtEnergy;
    private TextView txtNextWave;
    private Button btnShop;
    private Button btnBattlePass;
    private Button btnDailyRewards;
    private Button btnGuild;
    private Button btnLeaderboard;
    private Button btnSettings;

    private Handler gameLoopHandler;
    private Runnable gameLoopRunnable;
    private static final int GAME_LOOP_DELAY_MS = 33; // ~30 FPS

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        // Get singleton managers
        SurvivalMergeApp app = (SurvivalMergeApp) getApplication();
        gameManager = app.getGameManager();
        monetizationManager = app.getMonetizationManager();
        firebaseManager = app.getFirebaseManager();

        // Initialize UI
        initializeUI();

        // Initialize or load player
        initializePlayer();

        // REQUIREMENT #9: Request notification permission for Android 13+
        requestNotificationPermission();

        // Start game loop
        startGameLoop();
    }

    private void initializeUI() {
        txtLevel = findViewById(R.id.txt_level);
        txtWave = findViewById(R.id.txt_wave);
        txtScore = findViewById(R.id.txt_score);
        txtGold = findViewById(R.id.txt_gold);
        txtGems = findViewById(R.id.txt_gems);
        txtEnergy = findViewById(R.id.txt_energy);
        txtNextWave = findViewById(R.id.txt_next_wave);

        btnShop = findViewById(R.id.btn_shop);
        btnBattlePass = findViewById(R.id.btn_battle_pass);
        btnDailyRewards = findViewById(R.id.btn_daily_rewards);
        btnGuild = findViewById(R.id.btn_guild);
        btnLeaderboard = findViewById(R.id.btn_leaderboard);
        btnSettings = findViewById(R.id.btn_settings);

        // Set click listeners
        btnShop.setOnClickListener(v -> openShop());
        btnBattlePass.setOnClickListener(v -> openBattlePass());
        btnDailyRewards.setOnClickListener(v -> openDailyRewards());
        btnGuild.setOnClickListener(v -> openGuild());
        btnLeaderboard.setOnClickListener(v -> openLeaderboard());
        btnSettings.setOnClickListener(v -> openSettings());

        findViewById(R.id.btn_play).setOnClickListener(v -> startGame());
    }

    private void initializePlayer() {
        // Try to load from Firebase
        firebaseManager.signInAnonymously(new FirebaseManager.AuthCallback() {
            @Override
            public void onSuccess(String userId) {
                // Load player data
                firebaseManager.loadPlayerData(new FirebaseManager.PlayerDataCallback() {
                    @Override
                    public void onSuccess(Player loadedPlayer) {
                        player = loadedPlayer;
                        player.updateEnergy();
                        player.updateLoginStreak();
                        monetizationManager.setPlayer(player);
                        updateUI();
                    }

                    @Override
                    public void onFailure(Exception e) {
                        // Create new player
                        createNewPlayer(userId);
                    }
                });
            }

            @Override
            public void onFailure(Exception e) {
                // Create offline player
                createNewPlayer("offline_" + System.currentTimeMillis());
            }
        });
    }

    private void createNewPlayer(String userId) {
        player = new Player(userId, "Player");
        player.updateLoginStreak();
        monetizationManager.setPlayer(player);
        firebaseManager.savePlayerData(player);
        updateUI();
    }

    /**
     * REQUIREMENT #9: Android 13+ notification permission
     * Required for targetSdk 35 (Android 15)
     */
    private void requestNotificationPermission() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ContextCompat.checkSelfPermission(this, Manifest.permission.POST_NOTIFICATIONS)
                != PackageManager.PERMISSION_GRANTED) {

                // Show educational dialog first
                new AlertDialog.Builder(this)
                    .setTitle(R.string.txt_notification_permission_title)
                    .setMessage(R.string.txt_notification_permission_message)
                    .setPositiveButton(R.string.btn_allow, (dialog, which) -> {
                        ActivityCompat.requestPermissions(this,
                            new String[]{Manifest.permission.POST_NOTIFICATIONS},
                            NOTIFICATION_PERMISSION_REQUEST);
                    })
                    .setNegativeButton(R.string.btn_not_now, null)
                    .show();
            }
        }
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions,
                                          @NonNull int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        if (requestCode == NOTIFICATION_PERMISSION_REQUEST) {
            if (grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                // Permission granted
                Toast.makeText(this, "Notifications enabled!", Toast.LENGTH_SHORT).show();
            }
        }
    }

    private void startGame() {
        if (gameManager.startGame(player)) {
            // Game started successfully
            Toast.makeText(this, "Game started! Defend against the waves!", Toast.LENGTH_SHORT).show();
        } else {
            // Not enough energy
            Toast.makeText(this, R.string.error_no_internet, Toast.LENGTH_SHORT).show();
            // Offer rewarded ad to refill energy
            offerEnergyRefill();
        }
    }

    private void offerEnergyRefill() {
        new AlertDialog.Builder(this)
            .setTitle("Out of Energy!")
            .setMessage("Watch an ad to get 20 energy?")
            .setPositiveButton("Watch Ad", (dialog, which) -> {
                monetizationManager.showRewardedAd(this, amount -> {
                    Toast.makeText(this, "Energy refilled!", Toast.LENGTH_SHORT).show();
                    updateUI();
                });
            })
            .setNegativeButton("Cancel", null)
            .show();
    }

    private void startGameLoop() {
        gameLoopHandler = new Handler();
        gameLoopRunnable = new Runnable() {
            private long lastUpdateTime = System.currentTimeMillis();

            @Override
            public void run() {
                long currentTime = System.currentTimeMillis();
                float deltaTime = (currentTime - lastUpdateTime) / 1000.0f;
                lastUpdateTime = currentTime;

                // Update game state
                gameManager.update(deltaTime);

                // Update UI
                updateUI();

                // Schedule next frame
                gameLoopHandler.postDelayed(this, GAME_LOOP_DELAY_MS);
            }
        };
        gameLoopHandler.post(gameLoopRunnable);
    }

    private void updateUI() {
        if (player == null) return;

        txtLevel.setText(getString(R.string.txt_level, player.getLevel()));
        txtWave.setText(getString(R.string.txt_wave, gameManager.getCurrentWave()));
        txtScore.setText(getString(R.string.txt_score, gameManager.getScore()));
        txtGold.setText(getString(R.string.txt_gold, player.getGold()));
        txtGems.setText(getString(R.string.txt_gems, player.getGems()));
        txtEnergy.setText(getString(R.string.txt_energy, player.getEnergy(), player.getMaxEnergy()));
        txtNextWave.setText(getString(R.string.txt_next_wave, gameManager.getTimeUntilNextWave()));
    }

    private void openShop() {
        startActivity(new Intent(this, ShopActivity.class));
    }

    private void openBattlePass() {
        startActivity(new Intent(this, BattlePassActivity.class));
    }

    private void openDailyRewards() {
        startActivity(new Intent(this, DailyRewardsActivity.class));
    }

    private void openGuild() {
        startActivity(new Intent(this, GuildActivity.class));
    }

    private void openLeaderboard() {
        startActivity(new Intent(this, LeaderboardActivity.class));
    }

    private void openSettings() {
        startActivity(new Intent(this, SettingsActivity.class));
    }

    @Override
    protected void onPause() {
        super.onPause();
        // Save player data
        if (player != null) {
            firebaseManager.savePlayerData(player);
        }
        // Stop game loop
        if (gameLoopHandler != null && gameLoopRunnable != null) {
            gameLoopHandler.removeCallbacks(gameLoopRunnable);
        }
    }

    @Override
    protected void onResume() {
        super.onResume();
        // Update energy
        if (player != null) {
            player.updateEnergy();
            updateUI();
        }
        // Resume game loop
        if (gameLoopHandler != null && gameLoopRunnable != null) {
            gameLoopHandler.post(gameLoopRunnable);
        }
    }
}
