import android.content.Context;
import com.fangames.survivalmerge.models.Enemy;
import com.fangames.survivalmerge.models.MergeItem;
import com.fangames.survivalmerge.models.Player;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Core game engine - manages merge grid, waves, and combat
 * Hybrid merge + tower defense mechanics
 */
public class GameManager {

    private static final int GRID_SIZE = 5;
    private static final int WAVE_INTERVAL_SECONDS = 60;
    private static final int ENERGY_COST_PER_RUN = 10;

    private Context context;
    private Player player;
    private MergeItem[][] mergeGrid;
    private List<Enemy> activeEnemies;
    private int currentWave;
    private long waveStartTime;
    private int score;
    private boolean gameRunning;
    private Random random;

    public GameManager(Context context) {
        this.context = context;
        this.mergeGrid = new MergeItem[GRID_SIZE][GRID_SIZE];
        this.activeEnemies = new ArrayList<>();
        this.random = new Random();
        this.currentWave = 0;
        this.score = 0;
        this.gameRunning = false;
    }

    public boolean startGame(Player player) {
        this.player = player;

        // Check energy
        if (!player.spendEnergy(ENERGY_COST_PER_RUN)) {
            return false; // Not enough energy
        }

        // Initialize game state
        resetGrid();
        activeEnemies.clear();
        currentWave = 0;
        score = 0;
        gameRunning = true;
        waveStartTime = System.currentTimeMillis();

        // Spawn initial tier 1 items
        spawnInitialItems();

        return true;
    }

    private void resetGrid() {
        for (int x = 0; x < GRID_SIZE; x++) {
            for (int y = 0; y < GRID_SIZE; y++) {
                mergeGrid[x][y] = null;
            }
        }
    }

    private void spawnInitialItems() {
        // Spawn 3 random tier 1 items to start
        String[] types = {"archer", "mage", "warrior", "cannon"};
        for (int i = 0; i < 3; i++) {
            int x = random.nextInt(GRID_SIZE);
            int y = random.nextInt(GRID_SIZE);
            if (mergeGrid[x][y] == null) {
                String type = types[random.nextInt(types.length)];
                mergeGrid[x][y] = new MergeItem(1, type, x, y);
            }
        }
    }

    /**
     * Main game update loop - call every frame
     */
    public void update(float deltaTime) {
        if (!gameRunning) return;

        // Check if wave should spawn
        long currentTime = System.currentTimeMillis();
        if (currentTime - waveStartTime >= WAVE_INTERVAL_SECONDS * 1000) {
            spawnWave();
            waveStartTime = currentTime;
        }

        // Update enemies
        updateEnemies(deltaTime);

        // Process combat
        processCombat();

        // Check win/lose conditions
        checkGameState();
    }

    private void spawnWave() {
        currentWave++;

        int enemyCount = 10 + (currentWave * 2); // More enemies each wave

        // Boss every 10 waves
        if (currentWave % 10 == 0) {
            activeEnemies.add(new Enemy(Enemy.Type.BOSS, currentWave));
        }

        // Spawn varied enemy types
        for (int i = 0; i < enemyCount; i++) {
            Enemy.Type type = getRandomEnemyType();
            activeEnemies.add(new Enemy(type, currentWave));
        }
    }

    private Enemy.Type getRandomEnemyType() {
        int roll = random.nextInt(100);
        if (roll < 40) return Enemy.Type.WALKER;
        if (roll < 60) return Enemy.Type.RUNNER;
        if (roll < 75) return Enemy.Type.TANK;
        if (roll < 85) return Enemy.Type.SPITTER;
        if (roll < 95) return Enemy.Type.EXPLODER;
        return Enemy.Type.HORDE;
    }

    private void updateEnemies(float deltaTime) {
        for (int i = activeEnemies.size() - 1; i >= 0; i--) {
            Enemy enemy = activeEnemies.get(i);
            enemy.move(deltaTime);

            if (enemy.reachedEnd()) {
                // Game over if enemy reaches end
                gameRunning = false;
                activeEnemies.remove(i);
            }
        }
    }

    private void processCombat() {
        // Auto-defense: towers attack nearest enemies in range
        for (int x = 0; x < GRID_SIZE; x++) {
            for (int y = 0; y < GRID_SIZE; y++) {
                MergeItem tower = mergeGrid[x][y];
                if (tower != null) {
                    attackWithTower(tower);
                }
            }
        }

        // Remove dead enemies
        for (int i = activeEnemies.size() - 1; i >= 0; i--) {
            Enemy enemy = activeEnemies.get(i);
            if (enemy.isDead()) {
                // Reward player
                player.addGold(enemy.getGoldReward());
                player.addXP(10);
                player.addBattlePassXP(5);
                score += enemy.getGoldReward();
                activeEnemies.remove(i);
            }
        }
    }

    private void attackWithTower(MergeItem tower) {
        // Find nearest enemy in range
        Enemy target = null;
        float closestDist = Float.MAX_VALUE;

        for (Enemy enemy : activeEnemies) {
            float dist = 1.0f - enemy.getPosition(); // Distance from tower
            if (dist < closestDist) {
                closestDist = dist;
                target = enemy;
            }
        }

        if (target != null) {
            // Deal damage based on tower stats
            target.takeDamage(tower.getAttackPower());
        }
    }

    private void checkGameState() {
        // Game continues until player loses or quits
        // Endless mode with increasing difficulty
    }

    /**
     * Merge two items if possible
     */
    public boolean mergeItems(int x1, int y1, int x2, int y2) {
        MergeItem item1 = mergeGrid[x1][y1];
        MergeItem item2 = mergeGrid[x2][y2];

        if (item1 == null || item2 == null) return false;
        if (!item1.canMergeWith(item2)) return false;

        // Create merged item at first position
        MergeItem merged = item1.merge(item2);
        mergeGrid[x1][y1] = merged;
        mergeGrid[x2][y2] = null;

        // Reward XP for merging
        player.addXP(5);
        player.addBattlePassXP(2);

        return true;
    }

    /**
     * Move item from one grid position to another
     */
    public boolean moveItem(int fromX, int fromY, int toX, int toY) {
        if (toX < 0 || toX >= GRID_SIZE || toY < 0 || toY >= GRID_SIZE) {
            return false;
        }

        if (mergeGrid[toX][toY] != null) {
            // Try to merge instead
            return mergeItems(fromX, fromY, toX, toY);
        }

        // Move item
        MergeItem item = mergeGrid[fromX][fromY];
        if (item != null) {
            item.setGridX(toX);
            item.setGridY(toY);
            mergeGrid[toX][toY] = item;
            mergeGrid[fromX][fromY] = null;
            return true;
        }

