/**
 * Represents enemy zombies with 7 types and progressive difficulty
 */
public class Enemy {
    public enum Type {
        WALKER,      // Basic slow zombie
        RUNNER,      // Fast zombie
        TANK,        // High HP zombie
        SPITTER,     // Ranged attack
        EXPLODER,    // Explodes on death
        BOSS,        // Wave 10, 20, 30... bosses
        HORDE        // Large groups
    }

    private Type type;
    private int health;
    private int maxHealth;
    private float speed;        // Grid units per second
    private int damage;         // Damage to player if reaches end
    private int goldReward;
    private float position;     // Current position (0.0 = start, 1.0 = end)

    public Enemy(Type type, int waveNumber) {
        this.type = type;
        this.position = 0.0f;
        calculateStats(waveNumber);
    }

    private void calculateStats(int wave) {
        // Progressive difficulty scaling
        float waveMultiplier = 1.0f + (wave * 0.15f);

        switch (type) {
            case WALKER:
                this.maxHealth = (int)(50 * waveMultiplier);
                this.speed = 0.5f;
                this.damage = 5;
                this.goldReward = 10;
                break;
            case RUNNER:
                this.maxHealth = (int)(30 * waveMultiplier);
                this.speed = 1.2f;
                this.damage = 3;
                this.goldReward = 15;
                break;
            case TANK:
                this.maxHealth = (int)(150 * waveMultiplier);
                this.speed = 0.3f;
                this.damage = 10;
                this.goldReward = 25;
                break;
            case SPITTER:
                this.maxHealth = (int)(40 * waveMultiplier);
                this.speed = 0.6f;
                this.damage = 7;
                this.goldReward = 20;
                break;
            case EXPLODER:
                this.maxHealth = (int)(60 * waveMultiplier);
                this.speed = 0.7f;
                this.damage = 15;
                this.goldReward = 30;
                break;
            case BOSS:
                this.maxHealth = (int)(500 * waveMultiplier);
                this.speed = 0.4f;
                this.damage = 25;
                this.goldReward = 100;
                break;
            case HORDE:
                this.maxHealth = (int)(25 * waveMultiplier);
                this.speed = 0.8f;
                this.damage = 2;
                this.goldReward = 5;
                break;
        }
        this.health = this.maxHealth;
    }

    public void takeDamage(int damage) {
        this.health -= damage;
    }

    public boolean isDead() {
        return health <= 0;
    }

    public void move(float deltaTime) {
        this.position += speed * deltaTime * 0.1f; // 0.1 = grid unit conversion
    }

    public boolean reachedEnd() {
        return position >= 1.0f;
    }

    // Getters
    public Type getType() { return type; }
    public int getHealth() { return health; }
    public int getMaxHealth() { return maxHealth; }
    public float getSpeed() { return speed; }
    public int getDamage() { return damage; }
    public int getGoldReward() { return goldReward; }
    public float getPosition() { return position; }
}
